import { useEffect, useState } from "react";

/**
 * Ilustrasi ruang laundry isometrik untuk halaman login Alora SuperApp.
 * - Jam dinding, kalender, jendela (siang/malam) dan papan "Selamat Hari ..." mengikuti waktu saat ini.
 * - Logo di dinding memakai file di folder public: /waschen.webp, /ikm.png, /cleanox.png
 * - Animasi (mesin cuci berputar, uap setrika, baju bergoyang) berhenti otomatis bila pengguna
 *   mengaktifkan "reduce motion" di perangkatnya.
 */
const SCENE_CSS = `.lr-spin,.lr-spin2,.lr-spin3{transform-box:fill-box;transform-origin:center;animation:lr-spin 1.6s linear infinite}
.lr-spin2{animation-duration:2.4s;animation-direction:reverse}
.lr-spin3{animation-duration:4s}
@keyframes lr-spin{to{transform:rotate(360deg)}}
.lr-sway{transform-box:fill-box;transform-origin:50% 0;animation:lr-sway 3.8s ease-in-out infinite alternate}
@keyframes lr-sway{from{transform:rotate(-2.5deg)}to{transform:rotate(2.5deg)}}
.lr-steam{transform-box:fill-box;transform-origin:center;animation:lr-puff 2.6s ease-out infinite;opacity:0}
.lr-s2{animation-delay:-.9s}.lr-s3{animation-delay:-1.7s}
@keyframes lr-puff{0%{transform:translate(0,0) scale(.6);opacity:0}20%{opacity:.95}100%{transform:translate(-8px,-46px) scale(1.5);opacity:0}}
@media (prefers-reduced-motion: reduce){.lr-spin,.lr-spin2,.lr-spin3,.lr-sway{animation:none}.lr-steam{animation:none;opacity:.8}}`;

function timeTokens(n) {
    const h = n.getHours();
    const m = n.getMinutes();
    const night = h >= 18 || h < 6;
    const t = {
        hourDeg: (h % 12) * 30 + m * 0.5,
        minDeg: m * 6,
        sky: night ? "#2D3A6B" : "#9FD3F2",
        orb: night ? "#FFE9A8" : "#FFD54A",
    };
    for (let i = 0; i < 7; i++) t["o" + i] = n.getDay() === i ? 1 : 0;
    for (let i = 0; i < 12; i++) t["m" + i] = n.getMonth() === i ? 1 : 0;
    for (let i = 1; i <= 31; i++) t["t" + i] = n.getDate() === i ? 1 : 0;
    return t;
}

/**
 * Mesin pengering pendek (front-load, jendela persegi panjang) yang ditumpuk di atas mesin cuci.
 * (x, y) = sudut kiri-depan bagian atas mesin cuci di bawahnya. Lebar/dalam 2.2 unit, tinggi 1.1 unit.
 */
const DRYER_H = 41.8; // 1.1 unit x 38px
function Dryer({ x, y, id, spin }) {
    const p = (pts) => "M" + pts.map(([a, b]) => `${a.toFixed(1)} ${b.toFixed(1)}`).join(" L") + " Z";
    const W = 72.4, D = 41.8, H = DRYER_H; // W/D: offset isometrik 2.2 unit
    const ink = { stroke: "#3B1F2B", strokeWidth: 2.5, strokeLinejoin: "round" };
    const ns = { vectorEffect: "non-scaling-stroke" };
    const glass = "M0.40 0.24 H1.80 Q1.86 0.24 1.86 0.30 V0.70 Q1.86 0.76 1.80 0.76 H0.40 Q0.34 0.76 0.34 0.70 V0.63 H0.47 Q0.52 0.63 0.52 0.58 V0.42 Q0.52 0.37 0.47 0.37 H0.34 V0.30 Q0.34 0.24 0.40 0.24 Z";
    return (
        <g>
            <path d={p([[x, y - H], [x + W, y - H - D], [x + 2 * W, y - H], [x + W, y]])} fill="#FFFFFF" {...ink}></path>
            <path d={p([[x + W, y], [x + 2 * W, y - H], [x + 2 * W, y], [x + W, y + D]])} fill="#DCE3EE" {...ink}></path>
            <path d={p([[x, y - H], [x + W, y], [x + W, y + D], [x, y]])} fill="#F6F8FB" {...ink}></path>
            <g transform={`matrix(32.908 19.000 0 38.000 ${x} ${y - H})`}>
                <rect x="0.2" y="0.12" width="1.8" height="0.76" rx="0.08" fill="#FFFFFF" stroke="#3B1F2B" strokeWidth="2" {...ns}></rect>
                <clipPath id={id}><path d={glass}></path></clipPath>
                <g clipPath={`url(#${id})`}>
                    <rect x="0.3" y="0.2" width="1.6" height="0.6" fill="#3E4656"></rect>
                    <ellipse cx="1.15" cy="0.5" rx="0.55" ry="0.34" fill="#4E5869"></ellipse>
                    <g className={spin}>
                        <circle cx="1.15" cy="0.5" r="0.3" fill="none"></circle>
                        <path d="M0.95 0.36 Q1.08 0.28 1.22 0.36 Q1.2 0.48 1.06 0.47 Z" fill="#F57C00" opacity=".85"></path>
                        <path d="M1.2 0.56 Q1.34 0.52 1.4 0.64 Q1.28 0.72 1.16 0.66 Z" fill="#CFE2F5" opacity=".85"></path>
                        <path d="M0.9 0.56 Q0.98 0.66 0.9 0.74 Q0.8 0.66 0.9 0.56 Z" fill="#6B2D77" opacity=".85"></path>
                    </g>
                    <path d="M1.3 0.2 L1.0 0.8 M1.48 0.2 L1.2 0.8" stroke="#FFFFFF" strokeWidth="3" opacity=".22" {...ns}></path>
                </g>
                <path d={glass} fill="none" stroke="#3B1F2B" strokeWidth="2" {...ns}></path>
                <path d="M0.08 0.97 H2.12" stroke="#C9D2DE" strokeWidth="1.5" {...ns}></path>
            </g>
        </g>
    );
}

/**
 * Tumpukan baju terlipat (kerah terlihat di baju paling atas) yang dibungkus plastik packing berlogo Waschen.
 * (x, y) = sudut belakang bagian bawah tumpukan. layers: [warna atas, kanan, kiri] dari bawah ke atas.
 * Satu unit isometrik = (32.908, 19) ke kanan-bawah dan (-32.908, 19) ke kiri-bawah; 38px = 1 unit tinggi.
 */
const SHIRT_L = 1.4, SHIRT_W = 1.1, LAYER_H = 0.26, WRAP = 0.035;
function isoPt(x, y, a, b, h) {
    // a: unit ke kanan-bawah, b: unit ke kiri-bawah, h: unit ke atas
    return [x + 32.908 * (a - b), y + 19 * (a + b) - 38 * h];
}
const pts = (list) => "M" + list.map(([px, py]) => px.toFixed(1) + " " + py.toFixed(1)).join(" L") + " Z";
function isoBox(x, y, a0, b0, h0, la, lb, lh) {
    const P = (a, b, h) => isoPt(x, y, a0 + a, b0 + b, h0 + h);
    return {
        top: pts([P(0, 0, lh), P(la, 0, lh), P(la, lb, lh), P(0, lb, lh)]),
        right: pts([P(la, 0, lh), P(la, lb, lh), P(la, lb, 0), P(la, 0, 0)]),
        left: pts([P(0, lb, lh), P(la, lb, lh), P(la, lb, 0), P(0, lb, 0)]),
        R: P(la, 0, lh),
        L: P(0, lb, lh),
    };
}
function PackedStack({ x, y, layers }) {
    const ink = { stroke: "#3B1F2B", strokeWidth: 2, strokeLinejoin: "round" };
    const ns = { vectorEffect: "non-scaling-stroke" };
    const n = layers.length;
    const rightC = layers[n - 1][1]; // warna sisi gelap baju teratas, untuk garis lipatan & kancing
    const shirtTop = isoBox(x, y, 0, 0, 0, SHIRT_L, SHIRT_W, n * LAYER_H);
    const wrapH = n * LAYER_H + 0.05;
    const wrap = isoBox(x, y, -WRAP, -WRAP, 0, SHIRT_L + 2 * WRAP, SHIRT_W + 2 * WRAP, wrapH);
    const faceW = SHIRT_L + 2 * WRAP;
    const wrapB = isoPt(x, y, -WRAP, -WRAP, wrapH);
    return (
        <g>
            {layers.map(([t, r, l], i) => {
                const bx = isoBox(x, y, 0, 0, i * LAYER_H, SHIRT_L, SHIRT_W, LAYER_H);
                return (
                    <g key={i}>
                        <path d={bx.top} fill={t} {...ink}></path>
                        <path d={bx.right} fill={r} {...ink}></path>
                        <path d={bx.left} fill={l} {...ink}></path>
                    </g>
                );
            })}
            {/* Baju paling atas: kerah menghadap depan-kanan, kancing & lipatan lengan */}
            <g transform={`matrix(-32.908 19 -32.908 -19 ${shirtTop.R[0]} ${shirtTop.R[1]})`}>
                <path d="M0.2 0.42 V1.3 M0.9 0.42 V1.3" stroke={rightC} strokeWidth="1.5" {...ns}></path>
                <path d="M0.55 0.36 V1.32" stroke={rightC} strokeWidth="2" {...ns}></path>
                <circle cx="0.55" cy="0.55" r="0.03" fill="#FFFFFF" stroke="#3B1F2B" strokeWidth="1" {...ns}></circle>
                <circle cx="0.55" cy="0.8" r="0.03" fill="#FFFFFF" stroke="#3B1F2B" strokeWidth="1" {...ns}></circle>
                <circle cx="0.55" cy="1.05" r="0.03" fill="#FFFFFF" stroke="#3B1F2B" strokeWidth="1" {...ns}></circle>
                <path d="M0.28 0.2 Q0.28 0.02 0.55 0.02 Q0.82 0.02 0.82 0.2 Z" fill={rightC} stroke="#3B1F2B" strokeWidth="2" {...ns}></path>
                <path d="M0.28 0.2 Q0.28 0.02 0.55 0.02 Q0.82 0.02 0.82 0.2 L0.72 0.2 Q0.7 0.1 0.55 0.1 Q0.4 0.1 0.38 0.2 Z" fill="#FFFFFF" stroke="#3B1F2B" strokeWidth="2" strokeLinejoin="round" {...ns}></path>
                <path d="M0.38 0.18 L0.55 0.36 L0.3 0.46 L0.22 0.2 Z" fill="#FFFFFF" stroke="#3B1F2B" strokeWidth="2" strokeLinejoin="round" {...ns}></path>
                <path d="M0.72 0.18 L0.55 0.36 L0.8 0.46 L0.88 0.2 Z" fill="#FFFFFF" stroke="#3B1F2B" strokeWidth="2" strokeLinejoin="round" {...ns}></path>
            </g>
            {/* Plastik packing transparan */}
            <path d={wrap.left} fill="#FFFFFF" fillOpacity=".14" stroke="#9DB3C6" strokeWidth="1.5" strokeLinejoin="round"></path>
            <path d={wrap.right} fill="#FFFFFF" fillOpacity=".1" stroke="#9DB3C6" strokeWidth="1.5" strokeLinejoin="round"></path>
            <path d={wrap.top} fill="#FFFFFF" fillOpacity=".14" stroke="#9DB3C6" strokeWidth="1.5" strokeLinejoin="round"></path>
            <g transform={`matrix(-32.908 19 -32.908 -19 ${wrap.R[0]} ${wrap.R[1]})`}>
                <path d="M0.12 1.0 L0.32 1.42 M0.22 0.9 L0.36 1.18 M0.95 0.12 L1.12 0.42" stroke="#FFFFFF" strokeWidth="3" strokeLinecap="round" opacity=".85" {...ns}></path>
            </g>
            {/* Garis segel plastik di sisi depan */}
            <g transform={`matrix(32.908 19 0 38 ${wrap.L[0]} ${wrap.L[1]})`}>
                <path d={`M0.06 0.05 H${(faceW - 0.06).toFixed(2)}`} stroke="#B9C9D8" strokeWidth="1.5" strokeDasharray="3 2" {...ns}></path>
            </g>
            {/* Logo Waschen tercetak di atas plastik (transparan, tanpa latar) */}
            <g transform={`matrix(32.908 19 -32.908 19 ${wrapB[0]} ${wrapB[1]})`}>
                <image href="/waschen.webp" x="0.12" y="0.66" width="0.8" height="0.26" preserveAspectRatio="xMidYMid meet" opacity=".9"></image>
            </g>
        </g>
    );
}

